import json
# Reconstruct the 30x30 tiled input, including the clipped final row/column.
grid = [[0]*30 for _ in range(30)]
centers = [[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts = [1,8,15,22,29]
for tr,r0 in enumerate(starts):
    for tc,c0 in enumerate(starts):
        for dr in range(5):
            for dc in range(5):
                r,c=r0+dr,c0+dc
                if r<30 and c<30:
                    grid[r][c] = centers[tr][tc] if tr<4 and tc<4 and 1<=dr<=3 and 1<=dc<=3 else 4
# Connect matching non-background centers (3 and 8) through blank separators.
# Horizontal connectors: span between equal-color marker tiles in each tile row.
for tr in range(4):
    r = starts[tr]+2
    for color in (3,8):
        cols=[tc for tc in range(4) if centers[tr][tc]==color]
        if len(cols)>=2:
            for a,b in zip(cols,cols[1:]):
                for tc in range(a,b):
                    for c in range(starts[tc]+5, starts[tc]+7): grid[r][c]=color
# Vertical connectors.
for tc in range(4):
    c=starts[tc]+2
    for color in (3,8):
        rows=[tr for tr in range(4) if centers[tr][tc]==color]
        if len(rows)>=2:
            for a,b in zip(rows,rows[1:]):
                for tr in range(a,b):
                    for r in range(starts[tr]+5, starts[tr]+7): grid[r][c]=color
print(json.dumps(grid,separators=(',',':')))

